BEGIN;

-- One current position per profile and exact target.
CREATE TABLE "ProgressPositionTypes" (
    "Id" smallint PRIMARY KEY,
    "Key" varchar(32) NOT NULL UNIQUE
);
INSERT INTO "ProgressPositionTypes" ("Id", "Key") VALUES (1, 'Time'), (2, 'Reading'), (3, 'Game');

CREATE TABLE "MediaProgress" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ProfileId" bigint NOT NULL REFERENCES "Profiles" ("Id") ON DELETE CASCADE,
    "WorkId" bigint NOT NULL REFERENCES "Works" ("Id") ON DELETE CASCADE,
    "WorkUnitId" bigint NULL,
    "ProgressPositionTypeId" smallint NOT NULL REFERENCES "ProgressPositionTypes" ("Id"),
    "PositionMs" bigint NULL CHECK ("PositionMs" >= 0),
    "DurationMs" bigint NULL CHECK ("DurationMs" > 0),
    "IsCompleted" boolean NOT NULL DEFAULT FALSE,
    "CompletedAt" timestamptz NULL,
    "Locator" varchar(128) NULL,
    "Progression" numeric(5, 4) NULL CHECK ("Progression" BETWEEN 0 AND 1),
    "UpdatedAt" timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY ("WorkId", "WorkUnitId") REFERENCES "WorkUnits" ("WorkId", "Id") ON DELETE CASCADE,
    CHECK ("ProgressPositionTypeId" <> 1 OR "PositionMs" IS NOT NULL),
    CHECK ("IsCompleted" = ("CompletedAt" IS NOT NULL)),
    CHECK ("ProgressPositionTypeId" <> 2 OR "Locator" IS NOT NULL)
);
CREATE UNIQUE INDEX "UX_MediaProgress_Target" ON "MediaProgress" ("ProfileId", "WorkId", "WorkUnitId") NULLS NOT DISTINCT;
CREATE INDEX "IX_MediaProgress_Recent" ON "MediaProgress" ("ProfileId", "UpdatedAt" DESC, "Id" DESC);

-- A media server user and the profile whose progress it shares. A proposed profile waits for an administrator;
-- a confirmed link without a profile shares nothing.
CREATE TABLE "ProviderProfileLinks" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ProviderId" bigint NOT NULL REFERENCES "Providers" ("Id") ON DELETE CASCADE,
    "ExternalUserId" varchar(64) NOT NULL CHECK (length(btrim("ExternalUserId")) > 0),
    "ExternalName" varchar(200) NOT NULL CHECK (length(btrim("ExternalName")) > 0),
    "ProfileId" bigint NULL REFERENCES "Profiles" ("Id") ON DELETE CASCADE,
    "IsConfirmed" boolean NOT NULL DEFAULT FALSE,
    "SyncedAt" timestamptz NULL,
    UNIQUE ("ProviderId", "ExternalUserId")
);
CREATE UNIQUE INDEX "UX_ProviderProfileLinks_Profile" ON "ProviderProfileLinks" ("ProviderId", "ProfileId") WHERE "IsConfirmed";

-- The state last agreed with a media server per item; whichever side moved since then has changed.
CREATE TABLE "ProviderProgress" (
    "ProviderProfileLinkId" bigint NOT NULL REFERENCES "ProviderProfileLinks" ("Id") ON DELETE CASCADE,
    "ExternalItemId" varchar(64) NOT NULL,
    "PositionMs" bigint NOT NULL CHECK ("PositionMs" >= 0),
    "IsCompleted" boolean NOT NULL,
    "SyncedAt" timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY ("ProviderProfileLinkId", "ExternalItemId")
);

-- A profile's own AniList account. The token stays protected; sending progress is the profile's choice (PushEnabledAt) and only covers progress made after it.
-- One AniList user belongs to one profile.
CREATE TABLE "AniListConnections" (
    "ProfileId" bigint PRIMARY KEY REFERENCES "Profiles" ("Id") ON DELETE CASCADE,
    "ViewerId" integer NOT NULL UNIQUE CHECK ("ViewerId" > 0),
    "ViewerName" varchar(64) NOT NULL CHECK (length(btrim("ViewerName")) > 0),
    "ProtectedToken" bytea NOT NULL,
    "ExpiresAt" timestamptz NULL,
    "ConnectedAt" timestamptz NOT NULL DEFAULT now(),
    "PushEnabledAt" timestamptz NULL,
    "SyncedAt" timestamptz NULL,
    -- The last pass's failure (a code), cleared by the next good one.
    "FailureCode" varchar(64) NULL
);

-- The profile's AniList list as last read. An entry whose title is no Work (or season) yet waits as a pending match; nothing creates a Work for it.
-- RemoteUpdatedAt is the entry's state in AniList; ImportedUpdatedAt the state last taken over, so progress a person took back in Jularr is not imported again.
CREATE TABLE "AniListEntries" (
    "ProfileId" bigint NOT NULL REFERENCES "AniListConnections" ("ProfileId") ON DELETE CASCADE,
    "MediaId" integer NOT NULL CHECK ("MediaId" > 0),
    "ListEntryId" bigint NOT NULL CHECK ("ListEntryId" > 0),
    "IsManga" boolean NOT NULL,
    "Title" varchar(500) NOT NULL CHECK (length(btrim("Title")) > 0),
    "Status" varchar(16) NOT NULL CHECK ("Status" IN ('CURRENT', 'PLANNING', 'COMPLETED', 'DROPPED', 'PAUSED', 'REPEATING')),
    "Progress" integer NOT NULL CHECK ("Progress" >= 0),
    "ProgressVolumes" integer NOT NULL DEFAULT 0 CHECK ("ProgressVolumes" >= 0),
    -- Points out of a hundred, whatever format the person's AniList shows; 0 is unscored.
    "Score" smallint NOT NULL DEFAULT 0 CHECK ("Score" BETWEEN 0 AND 100),
    "TotalCount" integer NULL CHECK ("TotalCount" > 0),
    "TotalVolumes" integer NULL CHECK ("TotalVolumes" > 0),
    "RemoteUpdatedAt" timestamptz NOT NULL,
    "ImportedUpdatedAt" timestamptz NULL,
    -- When the profile's progress for the entry was last looked at for sending; only progress made after it is looked at again.
    "PushCheckedAt" timestamptz NULL,
    "AttemptCount" smallint NOT NULL DEFAULT 0 CHECK ("AttemptCount" >= 0),
    "NextAttemptAt" timestamptz NULL,
    "LastError" varchar(64) NULL,
    PRIMARY KEY ("ProfileId", "MediaId")
);

-- What an entry covers in the library: a film, the episodes of a season (numbered as AniList numbers them), or the volumes of a book.
CREATE VIEW "AniListEntryUnits" AS
SELECT
    entry."ProfileId",
    entry."MediaId",
    unit."WorkId",
    unit."Id" AS "WorkUnitId",
    (unit."Number" - mapped."EpisodeOffset")::integer AS "Number"
FROM
    "AniListEntries" AS entry
    JOIN "WorkUnitExternalIdentities" AS mapped ON mapped."Namespace" = 'anilist' AND mapped."Value" = entry."MediaId"::text
    JOIN "WorkUnits" AS unit ON unit."ParentWorkUnitId" = mapped."WorkUnitId" AND unit."WorkUnitTypeId" = 2
WHERE
    NOT entry."IsManga"
    AND unit."Number" > mapped."EpisodeOffset"
    AND unit."Number" = floor(unit."Number")
    AND NOT EXISTS (
        SELECT
            1
        FROM
            "WorkUnitExternalIdentities" AS later
        WHERE
            later."Namespace" = 'anilist'
            AND later."WorkUnitId" = mapped."WorkUnitId"
            AND later."EpisodeOffset" > mapped."EpisodeOffset"
            AND later."EpisodeOffset" < unit."Number"
    )
UNION ALL
SELECT
    entry."ProfileId",
    entry."MediaId",
    work."Id",
    NULL::bigint,
    1
FROM
    "AniListEntries" AS entry
    JOIN "WorkExternalIdentities" AS identity ON identity."Namespace" = 'anilist' AND identity."Value" = entry."MediaId"::text
    JOIN "Works" AS work ON work."Id" = identity."WorkId" AND work."MediaTypeId" = 1
WHERE
    NOT entry."IsManga"
UNION ALL
SELECT
    entry."ProfileId",
    entry."MediaId",
    unit."WorkId",
    unit."Id",
    unit."Number"::integer
FROM
    "AniListEntries" AS entry
    JOIN "WorkExternalIdentities" AS identity ON identity."Namespace" = 'anilist' AND identity."Value" = entry."MediaId"::text
    JOIN "Works" AS work ON work."Id" = identity."WorkId" AND work."MediaTypeId" = 3
    JOIN "WorkUnits" AS unit ON unit."WorkId" = work."Id" AND unit."WorkUnitTypeId" = 3
WHERE
    entry."IsManga"
    AND unit."Number" >= 1
    AND unit."Number" = floor(unit."Number");

-- A profile's saves of a game file, opaque to the server: the console's own save memory and one save state.
-- Play time is the game's MediaProgress (type Game, PositionMs played).
CREATE TABLE "GameSaveTypes" (
    "Id" smallint PRIMARY KEY,
    "Key" varchar(32) NOT NULL UNIQUE
);
INSERT INTO "GameSaveTypes" ("Id", "Key") VALUES (1, 'Memory'), (2, 'State');

CREATE TABLE "GameSaves" (
    "ProfileId" bigint NOT NULL REFERENCES "Profiles" ("Id") ON DELETE CASCADE,
    "MediaAssetId" bigint NOT NULL REFERENCES "MediaAssets" ("Id") ON DELETE CASCADE,
    "GameSaveTypeId" smallint NOT NULL REFERENCES "GameSaveTypes" ("Id"),
    "Data" bytea NOT NULL CHECK (octet_length("Data") BETWEEN 1 AND 16777216),
    "UpdatedAt" timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY ("ProfileId", "MediaAssetId", "GameSaveTypeId")
);
CREATE INDEX "IX_GameSaves_MediaAsset" ON "GameSaves" ("MediaAssetId");

-- Active and ended playback; ended sessions are the playback history.
CREATE TABLE "PlaybackModeTypes" (
    "Id" smallint PRIMARY KEY,
    "Key" varchar(32) NOT NULL UNIQUE
);
INSERT INTO "PlaybackModeTypes" ("Id", "Key") VALUES (1, 'DirectPlay'), (2, 'Remux'), (3, 'Transcode');

CREATE TABLE "PlaybackSessions" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "PublicId" uuid NOT NULL UNIQUE,
    "ProfileId" bigint NOT NULL REFERENCES "Profiles" ("Id") ON DELETE CASCADE,
    "MediaAssetId" bigint NOT NULL REFERENCES "MediaAssets" ("Id") ON DELETE CASCADE,
    "StoredFileId" bigint NOT NULL REFERENCES "StoredFiles" ("Id") ON DELETE CASCADE,
    "PlaybackModeTypeId" smallint NOT NULL REFERENCES "PlaybackModeTypes" ("Id"),
    "PositionMs" bigint NOT NULL DEFAULT 0 CHECK ("PositionMs" >= 0),
    "StartedAt" timestamptz NOT NULL DEFAULT now(),
    "LastSeenAt" timestamptz NOT NULL DEFAULT now(),
    "EndedAt" timestamptz NULL
);
CREATE INDEX "IX_PlaybackSessions_Profile" ON "PlaybackSessions" ("ProfileId", "StartedAt" DESC, "Id" DESC);
CREATE INDEX "IX_PlaybackSessions_Active" ON "PlaybackSessions" ("LastSeenAt") WHERE "EndedAt" IS NULL;

-- Prepared reading content; one document per content and analyzer version, shared by every profile.
CREATE TABLE "ReadingFormatTypes" (
    "Id" smallint PRIMARY KEY,
    "Key" varchar(32) NOT NULL UNIQUE
);
INSERT INTO "ReadingFormatTypes" ("Id", "Key") VALUES (1, 'Epub'), (2, 'Pdf'), (3, 'Smart'), (4, 'Comic');

CREATE TABLE "ReadingDocuments" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "StoredFileId" bigint NULL REFERENCES "StoredFiles" ("Id") ON DELETE SET NULL,
    "SourceSizeBytes" bigint NOT NULL CHECK ("SourceSizeBytes" >= 0),
    "SourceModifiedAt" timestamptz NOT NULL,
    "ContentHash" bytea NOT NULL CHECK (length("ContentHash") = 32),
    "AnalyzerVersion" integer NOT NULL CHECK ("AnalyzerVersion" > 0),
    "ReadingFormatTypeId" smallint NOT NULL REFERENCES "ReadingFormatTypes" ("Id"),
    "Title" varchar(500) NULL,
    "Language" varchar(35) NULL,
    "Structure" jsonb NOT NULL,
    "TotalCharacters" bigint NOT NULL CHECK ("TotalCharacters" >= 0),
    "CacheBytes" bigint NOT NULL DEFAULT 0 CHECK ("CacheBytes" >= 0),
    "CacheCompletedAt" timestamptz NULL,
    "LastReadAt" timestamptz NOT NULL DEFAULT now(),
    "CreatedAt" timestamptz NOT NULL DEFAULT now(),
    UNIQUE ("ContentHash", "AnalyzerVersion")
);
CREATE INDEX "IX_ReadingDocuments_File" ON "ReadingDocuments" ("StoredFileId");
CREATE INDEX "IX_ReadingDocuments_Cache" ON "ReadingDocuments" ("LastReadAt", "Id") WHERE "CacheBytes" > 0;

-- Cached sections and resources; eviction removes rows here only.
CREATE TABLE "ReadingResources" (
    "ReadingDocumentId" bigint NOT NULL REFERENCES "ReadingDocuments" ("Id") ON DELETE CASCADE,
    "Path" varchar(1024) NOT NULL CHECK (length("Path") > 0),
    "MediaType" varchar(128) NOT NULL,
    "Bytes" bytea NOT NULL,
    PRIMARY KEY ("ReadingDocumentId", "Path")
);

-- A profile's highlights and notes in a book file: block and character offsets of the prepared text, the quote stays readable when the book changes.
CREATE TABLE "ReadingAnnotations" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ProfileId" bigint NOT NULL REFERENCES "Profiles" ("Id") ON DELETE CASCADE,
    "MediaAssetId" bigint NOT NULL REFERENCES "MediaAssets" ("Id") ON DELETE CASCADE,
    "SectionIndex" integer NOT NULL CHECK ("SectionIndex" >= 0),
    "StartBlock" integer NOT NULL CHECK ("StartBlock" >= 0),
    "StartOffset" integer NOT NULL CHECK ("StartOffset" >= 0),
    "EndBlock" integer NOT NULL CHECK ("EndBlock" >= 0),
    "EndOffset" integer NOT NULL CHECK ("EndOffset" >= 0),
    "Quote" varchar(1000) NOT NULL CHECK (length(btrim("Quote")) > 0),
    "Note" varchar(4000) NULL CHECK (length(btrim("Note")) > 0),
    "HighlightColorTypeId" smallint NOT NULL CHECK ("HighlightColorTypeId" BETWEEN 1 AND 4),
    "CreatedAt" timestamptz NOT NULL DEFAULT now(),
    "UpdatedAt" timestamptz NOT NULL DEFAULT now(),
    CHECK (("StartBlock", "StartOffset") < ("EndBlock", "EndOffset"))
);
CREATE INDEX "IX_ReadingAnnotations_Asset" ON "ReadingAnnotations" ("ProfileId", "MediaAssetId", "SectionIndex", "StartBlock");

-- A profile's bookmarks in a book file: prose by section and block, an image book by page (its section index); at most one per place.
CREATE TABLE "ReadingBookmarks" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ProfileId" bigint NOT NULL REFERENCES "Profiles" ("Id") ON DELETE CASCADE,
    "MediaAssetId" bigint NOT NULL REFERENCES "MediaAssets" ("Id") ON DELETE CASCADE,
    "SectionIndex" integer NOT NULL CHECK ("SectionIndex" >= 0),
    "Block" integer NOT NULL CHECK ("Block" >= 0),
    "Progression" numeric(5, 4) NOT NULL CHECK ("Progression" BETWEEN 0 AND 1),
    "Title" varchar(500) NULL CHECK (length(btrim("Title")) > 0),
    "CreatedAt" timestamptz NOT NULL DEFAULT now(),
    UNIQUE ("ProfileId", "MediaAssetId", "SectionIndex", "Block")
);

-- What a profile chose for a book on all its devices: the language it reads in ("original" or a language code) and, for a book with a PDF, the view (1 Smart Book, 2 Original pages).
-- Without a language the book follows the profile's language; without a view the choice is automatic by the quality of the reading text.
CREATE TABLE "ReadingViewTypes" (
    "Id" smallint PRIMARY KEY,
    "Key" varchar(32) NOT NULL UNIQUE
);
INSERT INTO "ReadingViewTypes" ("Id", "Key") VALUES (1, 'Smart'), (2, 'Original');

CREATE TABLE "ReadingPreferences" (
    "ProfileId" bigint NOT NULL REFERENCES "Profiles" ("Id") ON DELETE CASCADE,
    "WorkId" bigint NOT NULL REFERENCES "Works" ("Id") ON DELETE CASCADE,
    "Language" varchar(8) NULL CHECK ("Language" = 'original' OR "Language" ~ '^[a-z]{2,3}$'),
    "ReadingViewTypeId" smallint NULL REFERENCES "ReadingViewTypes" ("Id"),
    "UpdatedAt" timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY ("ProfileId", "WorkId"),
    CHECK ("Language" IS NOT NULL OR "ReadingViewTypeId" IS NOT NULL)
);

-- How a profile's reading text looks on all its devices: typeface (1 serif, 2 sans), size in pixels, line and paragraph spacing in percent, text width in characters and hyphenation.
-- A profile without a row reads with these defaults.
CREATE TABLE "ProfileReaderSettings" (
    "ProfileId" bigint PRIMARY KEY REFERENCES "Profiles" ("Id") ON DELETE CASCADE,
    "FontTypeId" smallint NOT NULL DEFAULT 1 CHECK ("FontTypeId" IN (1, 2)),
    "Size" integer NOT NULL DEFAULT 20 CHECK ("Size" BETWEEN 14 AND 40),
    "LineSpacing" integer NOT NULL DEFAULT 165 CHECK ("LineSpacing" BETWEEN 120 AND 220),
    "ParagraphSpacing" integer NOT NULL DEFAULT 100 CHECK ("ParagraphSpacing" BETWEEN 0 AND 200),
    "TextWidth" integer NOT NULL DEFAULT 68 CHECK ("TextWidth" BETWEEN 40 AND 90),
    "Hyphenation" boolean NOT NULL DEFAULT TRUE,
    "UpdatedAt" timestamptz NOT NULL DEFAULT now()
);

-- What a profile plays by default; a profile without a row plays the file's own audio, shows subtitles while the audio is foreign in the profile's language, at normal speed.
CREATE TABLE "ProfilePlaybackPreferences" (
    "ProfileId" bigint PRIMARY KEY REFERENCES "Profiles" ("Id") ON DELETE CASCADE,
    -- Two-letter codes; no audio language keeps the file's default track, no subtitle language follows the profile's language.
    "AudioLanguage" varchar(2) NULL CHECK ("AudioLanguage" ~ '^[a-z]{2}$'),
    "SubtitleLanguage" varchar(2) NULL CHECK ("SubtitleLanguage" ~ '^[a-z]{2}$'),
    -- 1 off, 2 forced only, 3 always, 4 only while the audio is foreign.
    "SubtitleModeTypeId" smallint NOT NULL DEFAULT 4 CHECK ("SubtitleModeTypeId" BETWEEN 1 AND 4),
    "Speed" numeric(3, 2) NOT NULL DEFAULT 1 CHECK ("Speed" BETWEEN 0.25 AND 4),
    "AutoplayNext" boolean NOT NULL DEFAULT TRUE,
    -- What happens at an intro (or recap) and at credits (or preview): 1 nothing, 2 a Skip button, 3 skipped by itself.
    "IntroSkipModeTypeId" smallint NOT NULL DEFAULT 2 CHECK ("IntroSkipModeTypeId" BETWEEN 1 AND 3),
    "OutroSkipModeTypeId" smallint NOT NULL DEFAULT 2 CHECK ("OutroSkipModeTypeId" BETWEEN 1 AND 3),
    -- Whether a card that lingers on a touch device plays its preview by itself.
    "AutoplayPreviews" boolean NOT NULL DEFAULT TRUE,
    "UpdatedAt" timestamptz NOT NULL DEFAULT now()
);

-- A scanned PDF whose pages the worker reads into text, a bounded few at a time; the page a reader has open comes first, a failed one waits for a changed file.
-- Pages is known once the first pass has looked at the file. A finished one keeps its pages: they are the derived text layer the reading copy is built from.
CREATE TABLE "ReadingRecognitions" (
    "StoredFileId" bigint NOT NULL PRIMARY KEY REFERENCES "StoredFiles" ("Id") ON DELETE CASCADE,
    "SourceSizeBytes" bigint NOT NULL CHECK ("SourceSizeBytes" >= 0),
    "SourceModifiedAt" timestamptz NOT NULL,
    "RequestedAt" timestamptz NOT NULL DEFAULT now(),
    "Pages" integer NULL CHECK ("Pages" >= 0),
    "WantedPage" integer NULL CHECK ("WantedPage" >= 1),
    "WantedAt" timestamptz NULL,
    "FailedAt" timestamptz,
    "FinishedAt" timestamptz
);

-- What the recognizer found on one page: its lines as fractions of the page (left, top, right, bottom, text, confidence) and how plausible the text is.
-- Reason: recognized, blank, text (the page already has text), undecodable (a picture the server cannot read, left to the original).
CREATE TABLE "ReadingRecognizedPages" (
    "StoredFileId" bigint NOT NULL REFERENCES "ReadingRecognitions" ("StoredFileId") ON DELETE CASCADE,
    "PageNumber" integer NOT NULL CHECK ("PageNumber" >= 1),
    "Reason" varchar(24) NOT NULL,
    "Quality" numeric(4, 3) NOT NULL CHECK ("Quality" BETWEEN 0 AND 1),
    "Lines" jsonb NOT NULL,
    PRIMARY KEY ("StoredFileId", "PageNumber")
);

-- A profile's note on a page of a book's PDF: the page number and the first words of the page's text where it has some, so the note finds its page again.
CREATE TABLE "ReadingPageNotes" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ProfileId" bigint NOT NULL REFERENCES "Profiles" ("Id") ON DELETE CASCADE,
    "MediaAssetId" bigint NOT NULL REFERENCES "MediaAssets" ("Id") ON DELETE CASCADE,
    "PageNumber" integer NOT NULL CHECK ("PageNumber" >= 1),
    "Anchor" varchar(200) NULL,
    "Note" varchar(4000) NOT NULL CHECK (length(btrim("Note")) > 0),
    "CreatedAt" timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX "IX_ReadingPageNotes_Asset" ON "ReadingPageNotes" ("ProfileId", "MediaAssetId", "PageNumber", "Id");

-- The reading copy of a PDF: an EPUB written beside it when that clearly helps. One row per PDF; a changed PDF or a newer analyzer converts it again.
-- Preparing is a running or interrupted attempt, Ready a written copy, Declined a PDF that stays as it is (scan, mostly pictures, unreliable text), Failed an error retried later.
CREATE TABLE "ReadingDerivationStatusTypes" (
    "Id" smallint PRIMARY KEY,
    "Key" varchar(32) NOT NULL UNIQUE
);
INSERT INTO "ReadingDerivationStatusTypes" ("Id", "Key") VALUES (1, 'Preparing'), (2, 'Ready'), (3, 'Declined'), (4, 'Failed');

CREATE TABLE "ReadingDerivations" (
    "StoredFileId" bigint NOT NULL PRIMARY KEY REFERENCES "StoredFiles" ("Id") ON DELETE CASCADE,
    "SourceSizeBytes" bigint NOT NULL CHECK ("SourceSizeBytes" >= 0),
    "SourceModifiedAt" timestamptz NOT NULL,
    "SourceSha256" bytea NULL CHECK (length("SourceSha256") = 32),
    "AnalyzerVersion" integer NOT NULL CHECK ("AnalyzerVersion" > 0),
    "ReadingDerivationStatusTypeId" smallint NOT NULL REFERENCES "ReadingDerivationStatusTypes" ("Id"),
    "Reason" varchar(32) NULL,
    "EbookStoredFileId" bigint NULL REFERENCES "StoredFiles" ("Id") ON DELETE SET NULL,
    "Pages" integer NULL CHECK ("Pages" >= 0),
    "Chapters" integer NULL CHECK ("Chapters" >= 0),
    "Figures" integer NULL CHECK ("Figures" >= 0),
    "Attempts" smallint NOT NULL DEFAULT 1 CHECK ("Attempts" > 0),
    "AttemptedAt" timestamptz NOT NULL DEFAULT now(),
    "FinishedAt" timestamptz NULL
);
CREATE UNIQUE INDEX "UX_ReadingDerivations_Ebook" ON "ReadingDerivations" ("EbookStoredFileId") WHERE "EbookStoredFileId" IS NOT NULL;

-- The files a book is read from: every stored file, except a derived EPUB whose copy is not ready or whose PDF has changed since. Readers choose among these.
CREATE VIEW "ReadableStoredFiles" AS
SELECT
    file."Id",
    file."MediaAssetId",
    file."LibraryRootId",
    file."RelativePath",
    file."SizeBytes",
    file."ModifiedAt",
    file."MissingSince",
    derivation."StoredFileId" IS NOT NULL AS "IsDerived",
    derivation."AnalyzerVersion" AS "DerivedAnalyzerVersion"
FROM
    "StoredFiles" AS file
    LEFT JOIN "ReadingDerivations" AS derivation ON derivation."EbookStoredFileId" = file."Id"
    LEFT JOIN "StoredFiles" AS source ON source."Id" = derivation."StoredFileId"
WHERE
    derivation."StoredFileId" IS NULL
    OR derivation."ReadingDerivationStatusTypeId" = 2
    AND source."SizeBytes" = derivation."SourceSizeBytes"
    AND source."ModifiedAt" = derivation."SourceModifiedAt";

-- How the server converts video: Auto follows the last benchmark's proposal (else the configured arguments), the others fix it.
CREATE TABLE "TranscodeAccelerationTypes" (
    "Id" smallint PRIMARY KEY,
    "Key" varchar(32) NOT NULL UNIQUE
);
INSERT INTO "TranscodeAccelerationTypes" ("Id", "Key") VALUES (1, 'Auto'), (2, 'Software'), (3, 'Vaapi'), (4, 'Qsv'), (5, 'Nvenc'), (6, 'VideoToolbox');

CREATE TABLE "TranscodeSettings" (
    "Id" bigint PRIMARY KEY CHECK ("Id" = 1),
    "TranscodeAccelerationTypeId" smallint NOT NULL DEFAULT 1 REFERENCES "TranscodeAccelerationTypes" ("Id"),
    -- Conversions at once, counted in 1080p streams; none follows the configuration.
    "MaxTranscodes" smallint NULL CHECK ("MaxTranscodes" BETWEEN 1 AND 64),
    -- Picture heights offered when the server has no room for the wanted conversion.
    "LadderHeights" integer[] NOT NULL DEFAULT '{1080,720,480}' CHECK (cardinality("LadderHeights") <= 6),
    "Version" bigint NOT NULL DEFAULT 1 CHECK ("Version" > 0)
);
INSERT INTO "TranscodeSettings" ("Id") VALUES (1);

-- The last hardware benchmark and what it proposes; a new run replaces it.
CREATE TABLE "TranscodeBenchmarks" (
    "Id" bigint PRIMARY KEY CHECK ("Id" = 1),
    "RanAt" timestamptz NOT NULL,
    "CpuCores" smallint NOT NULL CHECK ("CpuCores" > 0),
    "BestTranscodeAccelerationTypeId" smallint NOT NULL REFERENCES "TranscodeAccelerationTypes" ("Id") CHECK ("BestTranscodeAccelerationTypeId" > 1),
    "RecommendedMaxTranscodes" smallint NOT NULL CHECK ("RecommendedMaxTranscodes" BETWEEN 1 AND 64)
);

-- Seconds of picture converted per second of work; none: the pipeline did not run.
CREATE TABLE "TranscodeBenchmarkResults" (
    "TranscodeBenchmarkId" bigint NOT NULL DEFAULT 1 REFERENCES "TranscodeBenchmarks" ("Id") ON DELETE CASCADE,
    "TranscodeAccelerationTypeId" smallint NOT NULL REFERENCES "TranscodeAccelerationTypes" ("Id") CHECK ("TranscodeAccelerationTypeId" > 1),
    "Height" integer NOT NULL CHECK ("Height" > 0),
    "SpeedFactor" numeric(8, 2) NULL CHECK ("SpeedFactor" >= 0),
    PRIMARY KEY ("TranscodeBenchmarkId", "TranscodeAccelerationTypeId", "Height")
);

COMMIT;
